typedef struct {
    unsigned int ldt; /*timestamp of last BLE data received*/
    uint16_t val;
    int16_t  temp;    /*0.1 degC, signed*/
    uint16_t battmv;
    uint8_t pc;
    uint8_t hum;
    uint8_t batt;
    int8_t  rssi;
} sensor_env_t;

typedef struct {
    unsigned int ldt; /*timestamp of last BLE data received*/
    uint16_t val;
    uint16_t cent;
    uint16_t battmv;
    uint8_t batt;
    int8_t  rssi;
} sensor_tank_t;

typedef struct {
    uint16_t id;

#ifdef ENABLE_BLE
    bdaddr_t mac;
#endif
    char smac[20];
    char name[32];
    char zone[32];    /*AcquaThermoNet zone name (MQTT topic), default: name*/
    uint16_t polltime;
    /*env data*/
    sensor_env_t se;
    unsigned int ldst; /*timestamp of last MQTT data sent*/
    qint32  mqttPubId;
} sensor_t;

typedef struct {
    uint16_t port;
    char address[128];
    char uname[128];
    char password[128];
    char uniqueId[64];          /*client id RoomSense-<uniqueId>, empty: host name*/
    uint16_t publishInterval;   /*s, per zone while its sensor is heard*/
} mqtt_brk_t;

typedef union{
    uint16_t completo;
    struct{
        uint8_t basso;
        uint8_t alto;
    }__attribute__ ((packed));
    struct{
        uint16_t bit0		:1;
        uint16_t bit1		:1;
        uint16_t bit2		:1;
        uint16_t bit3		:1;
        uint16_t bit4		:1;
        uint16_t bit5		:1;
        uint16_t bit6		:1;
        uint16_t bit7		:1;
        uint16_t bit8		:1;
        uint16_t bit9		:1;
        uint16_t bit10		:1;
        uint16_t bit11		:1;
        uint16_t bit12		:1;
        uint16_t bit13		:1;
        uint16_t bit14		:1;
        uint16_t bit15		:1;
    }__attribute__ ((packed))bit;
}__attribute__ ((packed)) word_misto;

